        HeadlessApplication app = new HeadlessApplication(game, config);
        // Replace the framework's MockInput with our scripted subclass
        com.badlogic.gdx.Gdx.input = scriptedInput;
        // Register our InputProcessor on the new scripted input
        com.badlogic.gdx.Gdx.input.setInputProcessor(game);

        // Wait until the WalkerGame.create() has captured the headless main-loop thread
        Thread loopThread = null;
        long deadline = System.currentTimeMillis() + 5000L;
        while ((loopThread = game.getMainLoopThread()) == null && System.currentTimeMillis() < deadline) {
            Thread.sleep(5);
        }
        if (loopThread != null) {
            try {
                loopThread.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }

