        Gdx.input = scriptedInput;
        // Re-register input processor now that we replaced Gdx.input
        Gdx.input.setInputProcessor(game);

        // Drive the simulation in a separate thread: dispatch one key per tick then call Gdx.app.exit() when exhausted
        Thread driver = new Thread(() -> {
            try {
                while (!scriptedInput.isExhausted()) {
                    Thread.sleep(1000L / 60L);
                    // Dispatch on the application thread via postRunnable
                    final boolean[] done = {false};
                    Gdx.app.postRunnable(() -> {
                        scriptedInput.dispatchNext();
                        done[0] = true;
